// web-ui-phase-2 Group 4.1 — the joint SPA↔API contract regression for the
// items endpoints the Phase-2b SPA consumes. Black-box over the COMPOSED
// handler (web.Handler(api.New(deps))) — the exact surface behind /api/v1 —
// with a REAL store between the joints (no mocks; INV-black-box). It closes
// the gaps integration_web_test.go leaves open at the HTTP edge:
//
//  1. `library` is REQUIRED: absent/empty/non-integer -> 400 bad_request
//     (handlers.go listItems parses it unconditionally; previously only the
//     positive path ?library=1 was exercised).
//  2. limit/offset pagination AT THE HTTP EDGE: parsePagination defaults
//     (page 50), the maxLimit=200 clamp, windowed pages, invalid-value
//     fallback, and beyond-end -> {"items":[]} (store-level coverage existed
//     in store_test.go; the query-param parsing did not).
//  3. The itemDTO wire shape the SPA's ItemDTO mirrors verbatim — all nine
//     fields (id, module_id, library_id, file_id, relative_path, media_type,
//     document, schema_version, status) round-trip per entry.
//  4. Detail full-document BYTE fidelity with POPULATED sources/_view/
//     _provenance/_stages namespaces (integration_web_test.go's ac4 seeds
//     them empty): numbers, Cyrillic, and dynamic keys survive the
//     store→handler→wire path unmodified (delta: rendering fidelity's
//     server-side precondition).
//
// Status filtering is intentionally NOT re-tested here — in-package
// TestListItems_StatusFilter (internal/api/router_test.go) already owns that
// matrix; one confirming case rides along in the scoping sub-test.
package itest

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"testing"

	"github.com/mellifera/mellifera/internal/store"
)

// webItemWire is the test's view of one itemDTO entry (tags mirror
// internal/api/handlers.go itemDTO verbatim — the contract under test).
type webItemWire struct {
	ID            string          `json:"id"`
	ModuleID      string          `json:"module_id"`
	LibraryID     int64           `json:"library_id"`
	FileID        string          `json:"file_id"`
	RelativePath  string          `json:"relative_path"`
	MediaType     string          `json:"media_type"`
	Document      json.RawMessage `json:"document"`
	SchemaVersion int             `json:"schema_version"`
	Status        string          `json:"status"`
}

// webItemErrEnvelope decodes the full canonical error envelope
// {error:{code,message,retryable}} (webErrEnvelope covers code only).
type webItemErrEnvelope struct {
	Error struct {
		Code      string `json:"code"`
		Message   string `json:"message"`
		Retryable bool   `json:"retryable"`
	} `json:"error"`
}

// createWebLibrary creates a library row and returns its id.
func createWebLibrary(t *testing.T, st *store.Store, root, name string) int64 {
	t.Helper()
	id, err := st.CreateLibrary(context.Background(), "tv", root, name)
	if err != nil {
		t.Fatalf("CreateLibrary %s: %v", root, err)
	}
	return id
}

// seedWebItem inserts one item row with the given identity/status.
func seedWebItem(t *testing.T, st *store.Store, id string, libID int64, fid, status string) {
	t.Helper()
	err := st.PutItem(context.Background(), store.Item{
		ID: id, ModuleID: "tv", LibraryID: libID, FileID: fid,
		RelativePath: "/show/" + fid, MediaType: "video",
		Document: json.RawMessage(`{}`), SchemaVersion: 1, Status: status,
	})
	if err != nil {
		t.Fatalf("PutItem %s: %v", id, err)
	}
}

// webListItems GETs /api/v1/items<query> through the composed handler and
// decodes the itemsResponse. Fails the test on any non-200.
func webListItems(t *testing.T, h http.Handler, query string) []webItemWire {
	t.Helper()
	rec := webDo(t, h, webReq(http.MethodGet, "/api/v1/items"+query, webTestAdminToken, nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("GET /api/v1/items%s: status = %d, want 200 (body=%s)", query, rec.Code, rec.Body.String())
	}
	var resp struct {
		Items []webItemWire `json:"items"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
		t.Fatalf("decode items response: %v", err)
	}
	return resp.Items
}

// webItemIDs maps a listing to its ids IN ORDER (the wire order is the
// contract: store ORDER BY id must survive the handler untouched).
func webItemIDs(items []webItemWire) []string {
	ids := make([]string, len(items))
	for i, it := range items {
		ids[i] = it.ID
	}
	return ids
}

// assertIDOrder compares an actual id sequence against the wanted one.
func assertIDOrder(t *testing.T, path string, got, want []string) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("%s: got %v, want %v (len %d != %d)", path, got, want, len(got), len(want))
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("%s: got %v, want %v (order/page mismatch at %d)", path, got, want, i)
		}
	}
}

// assertItemWire asserts the nine itemDTO fields round-trip (field-by-field:
// json.RawMessage makes the struct non-comparable, and reflection is denied
// by depguard — explicit is the house style anyway). Document is asserted
// non-empty; byte fidelity is TestWeb_ItemDetailContract's job.
func assertItemWire(t *testing.T, got, want webItemWire) {
	t.Helper()
	if got.ID != want.ID {
		t.Errorf("id = %q, want %q", got.ID, want.ID)
	}
	if got.ModuleID != want.ModuleID {
		t.Errorf("module_id = %q, want %q", got.ModuleID, want.ModuleID)
	}
	if got.LibraryID != want.LibraryID {
		t.Errorf("library_id = %d, want %d", got.LibraryID, want.LibraryID)
	}
	if got.FileID != want.FileID {
		t.Errorf("file_id = %q, want %q", got.FileID, want.FileID)
	}
	if got.RelativePath != want.RelativePath {
		t.Errorf("relative_path = %q, want %q", got.RelativePath, want.RelativePath)
	}
	if got.MediaType != want.MediaType {
		t.Errorf("media_type = %q, want %q", got.MediaType, want.MediaType)
	}
	if got.SchemaVersion != want.SchemaVersion {
		t.Errorf("schema_version = %d, want %d", got.SchemaVersion, want.SchemaVersion)
	}
	if got.Status != want.Status {
		t.Errorf("status = %q, want %q", got.Status, want.Status)
	}
	if len(got.Document) == 0 {
		t.Errorf("document is empty — the list must carry the full document envelope")
	}
}

// requireWebLibraryParam asserts the library query param is REQUIRED and
// strictly integer-parsed: absent, empty, and non-integer all 400 bad_request
// with a non-retryable canonical envelope (the SPA always scopes to a library;
// a dropped selector must fail loudly, not list everything).
func requireWebLibraryParam(t *testing.T, h http.Handler) {
	t.Helper()
	for _, tc := range []struct{ name, query string }{
		{"absent", ""},
		{"empty", "?library="},
		{"non_integer", "?library=abc"},
	} {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			rec := webDo(t, h, webReq(http.MethodGet, "/api/v1/items"+tc.query, webTestAdminToken, nil))
			if rec.Code != http.StatusBadRequest {
				t.Fatalf("library %q: status = %d, want 400 (body=%s)", tc.query, rec.Code, rec.Body.String())
			}
			var env webItemErrEnvelope
			if err := json.Unmarshal(rec.Body.Bytes(), &env); err != nil {
				t.Fatalf("decode error envelope: %v", err)
			}
			if env.Error.Code != "bad_request" {
				t.Errorf("error.code = %q, want bad_request", env.Error.Code)
			}
			if env.Error.Retryable {
				t.Errorf("error.retryable = true, want false (client error)")
			}
			if env.Error.Message == "" {
				t.Errorf("error.message is empty — the SPA ErrorState needs it")
			}
		})
	}
}

// scopeStatusWire asserts (a) library scoping — a listing for libA never
// leaks libB rows; (b) one confirming status-filter case at the composed
// edge (the full matrix lives in internal/api/router_test.go); (c) the full
// itemDTO wire shape on a known entry.
func scopeStatusWire(t *testing.T, h http.Handler, libA, libB int64) {
	t.Helper()
	qA := "?library=" + strconv.FormatInt(libA, 10)
	all := webListItems(t, h, qA)
	if len(all) != 3 {
		t.Fatalf("libA listing = %d items, want 3", len(all))
	}
	for _, it := range all {
		if it.LibraryID != libA {
			t.Errorf("scoping leak: item %q has library_id=%d, want %d", it.ID, it.LibraryID, libA)
		}
	}
	ready := webListItems(t, h, qA+"&status=ready")
	assertIDOrder(t, "status=ready", webItemIDs(ready),
		[]string{"itm-web-a0", "itm-web-a1"})
	assertItemWire(t, ready[0], webItemWire{
		ID: "itm-web-a0", ModuleID: "tv", LibraryID: libA,
		FileID: "web-a0.mkv", RelativePath: "/show/web-a0.mkv", MediaType: "video",
		SchemaVersion: 1, Status: "ready",
	})
	// The other library's row must not appear under libA (cross-check libB's
	// own listing still sees its row — scoping, not data loss).
	assertIDOrder(t, "libB listing", webItemIDs(webListItems(t, h, "?library="+strconv.FormatInt(libB, 10))),
		[]string{"itm-web-b0"})
}

// paginationWindows seeds 5 zero-padded items and asserts limit/offset
// window the listing deterministically (ORDER BY id), invalid values fall
// back to the default, and an offset past the end yields [] not an error.
func paginationWindows(t *testing.T, h http.Handler, st *store.Store) {
	t.Helper()
	lib := createWebLibrary(t, st, "/paged", "Paged")
	for i := 1; i <= 5; i++ {
		seedWebItem(t, st, fmt.Sprintf("itm-page-%02d", i), lib,
			fmt.Sprintf("page-%02d.mkv", i), "ready")
	}
	q := "?library=" + strconv.FormatInt(lib, 10)
	for _, tc := range []struct {
		name  string
		query string
		want  []string
	}{
		{"no_params_returns_all", q, []string{"itm-page-01", "itm-page-02", "itm-page-03", "itm-page-04", "itm-page-05"}},
		{"limit2_offset0", q + "&limit=2&offset=0", []string{"itm-page-01", "itm-page-02"}},
		{"limit2_offset2_page2", q + "&limit=2&offset=2", []string{"itm-page-03", "itm-page-04"}},
		{"limit2_offset4_last", q + "&limit=2&offset=4", []string{"itm-page-05"}},
		{"offset_beyond_end_empty", q + "&offset=50", nil},
		{"limit_invalid_falls_to_default", q + "&limit=abc",
			[]string{"itm-page-01", "itm-page-02", "itm-page-03", "itm-page-04", "itm-page-05"}},
	} {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			assertIDOrder(t, tc.query, webItemIDs(webListItems(t, h, tc.query)), tc.want)
		})
	}
}

// paginationDefaultsAndCap seeds 201 items and pins the two named page-size
// constants at the HTTP edge: the default page (no limit) is 50 and a limit
// above the cap clamps to 200 (handlers.go defaultLimit/maxLimit — both
// named in the delta: "server default page size 50, max 200").
func paginationDefaultsAndCap(t *testing.T, h http.Handler, st *store.Store) {
	t.Helper()
	lib := createWebLibrary(t, st, "/capped", "Capped")
	for i := 0; i < 201; i++ {
		seedWebItem(t, st, fmt.Sprintf("itm-cap-%03d", i), lib,
			fmt.Sprintf("cap-%03d.mkv", i), "new")
	}
	q := "?library=" + strconv.FormatInt(lib, 10)
	if got := webListItems(t, h, q); len(got) != 50 {
		t.Errorf("no limit: %d items, want 50 (defaultLimit)", len(got))
	}
	capped := webListItems(t, h, q+"&limit=1000")
	if len(capped) != 200 {
		t.Errorf("limit=1000: %d items, want 200 (maxLimit clamp)", len(capped))
	}
	if len(capped) > 0 && capped[0].ID != "itm-cap-000" {
		t.Errorf("capped page starts at %q, want itm-cap-000 (deterministic order)", capped[0].ID)
	}
}

// TestWeb_ItemsListContract is the list-side half of the SPA↔API items
// contract (browse panel): library required, scoping + status, pagination.
func TestWeb_ItemsListContract(t *testing.T) {
	h, st := setupWebTest(t)
	libA := createWebLibrary(t, st, "/list-a", "ListA")
	seedWebItem(t, st, "itm-web-a0", libA, "web-a0.mkv", "ready")
	seedWebItem(t, st, "itm-web-a1", libA, "web-a1.mkv", "ready")
	seedWebItem(t, st, "itm-web-a2", libA, "web-a2.mkv", "new")
	libB := createWebLibrary(t, st, "/list-b", "ListB")
	seedWebItem(t, st, "itm-web-b0", libB, "web-b0.mkv", "ready")

	t.Run("library_required", func(t *testing.T) { requireWebLibraryParam(t, h) })
	t.Run("scoping_status_wire_shape", func(t *testing.T) { scopeStatusWire(t, h, libA, libB) })
	t.Run("pagination_windows", func(t *testing.T) { paginationWindows(t, h, st) })
	t.Run("pagination_defaults_and_cap", func(t *testing.T) { paginationDefaultsAndCap(t, h, st) })
}

// TestWeb_ItemDetailContract is the detail-side half: a POPULATED §3.1
// document (sources/_view/_provenance/_stages/identifiers/ffprobe + dynamic
// keys, numeric + Cyrillic content) survives store→handler→wire BYTE-faithful
// (compared compacted — whitespace-insensitive, format-sensitive), and a
// missing id 404s with the full canonical envelope the SPA ErrorState renders.
func TestWeb_ItemDetailContract(t *testing.T) {
	h, st := setupWebTest(t)
	lib := createWebLibrary(t, st, "/detail", "Detail")
	// Numbers stay literals (1234.5678901, 8.25, 400 — no float reformat),
	// Cyrillic passes through raw, "error":null survives, and an unknown
	// top-level namespace is never collapsed.
	fullDoc := json.RawMessage(`{` +
		`"identifiers":{"imdb":"tt1234567","title":"Сериал Лето"},` +
		`"sources":{` +
		`"tv-parser":{"title":"Сериал Лето","season":2,"episode":7,"rating":8.25},` +
		`"image-enricher":{"exif":{"gps":[55.751244,37.618423],"iso":400}}},` +
		`"ffprobe":{"duration":1234.5678901,"codec":"h264"},` +
		`"_view":{"poster":{"value":"http://example/p.jpg","source":"image-enricher","reason":"exif"}},` +
		`"_provenance":{"tv-parser":{"plugin_id":"tv-parser","at":"2026-10-05T00:00:00Z"}},` +
		`"_stages":{"parse":{"stage":"parse","plugin_id":"tv-parser","status":"done",` +
		`"advanced_to":"enrich","started_at":"2026-10-05T00:00:00Z",` +
		`"finished_at":"2026-10-05T00:00:01Z","error":null}},` +
		`"dynamic_extension":{"nested":[1,2,3]}}`)
	seedFullItem(t, st, "itm-web-detail", lib, fullDoc)

	t.Run("full_document_roundtrip", func(t *testing.T) {
		rec := webDo(t, h, webReq(http.MethodGet, "/api/v1/items/itm-web-detail", webTestAdminToken, nil))
		if rec.Code != http.StatusOK {
			t.Fatalf("get item: status = %d, want 200 (body=%s)", rec.Code, rec.Body.String())
		}
		var resp struct {
			Item webItemWire `json:"item"`
		}
		if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
			t.Fatalf("decode item response: %v", err)
		}
		assertItemWire(t, resp.Item, webItemWire{
			ID: "itm-web-detail", ModuleID: "tv", LibraryID: lib,
			FileID: "detail.mkv", RelativePath: "/show/detail.mkv", MediaType: "video",
			SchemaVersion: 1, Status: "enriched",
		})
		if got, want := compactJSON(t, resp.Item.Document), compactJSON(t, fullDoc); !bytes.Equal(got, want) {
			t.Errorf("document not byte-faithful through the wire:\n got  %s\n want %s", got, want)
		}
	})

	t.Run("not_found_envelope", func(t *testing.T) {
		rec := webDo(t, h, webReq(http.MethodGet, "/api/v1/items/itm-web-absent", webTestAdminToken, nil))
		if rec.Code != http.StatusNotFound {
			t.Fatalf("missing item: status = %d, want 404", rec.Code)
		}
		var env webItemErrEnvelope
		if err := json.Unmarshal(rec.Body.Bytes(), &env); err != nil {
			t.Fatalf("decode error envelope: %v", err)
		}
		if env.Error.Code != "not_found" {
			t.Errorf("error.code = %q, want not_found", env.Error.Code)
		}
		if env.Error.Retryable {
			t.Errorf("error.retryable = true, want false (a missing id is not retryable)")
		}
		if env.Error.Message == "" {
			t.Errorf("error.message is empty — the detail ErrorState needs code+message")
		}
	})
}

// seedFullItem inserts the detail-contract item with its populated document.
func seedFullItem(t *testing.T, st *store.Store, id string, libID int64, doc json.RawMessage) {
	t.Helper()
	err := st.PutItem(context.Background(), store.Item{
		ID: id, ModuleID: "tv", LibraryID: libID, FileID: "detail.mkv",
		RelativePath: "/show/detail.mkv", MediaType: "video",
		Document: doc, SchemaVersion: 1, Status: "enriched",
	})
	if err != nil {
		t.Fatalf("PutItem %s: %v", id, err)
	}
}

// compactJSON compacts a JSON document (drops insignificant whitespace,
// keeps number literals, string escapes, and key order byte-exact) so the
// wire document can be compared to the seeded one format-sensitively.
func compactJSON(t *testing.T, b []byte) []byte {
	t.Helper()
	var buf bytes.Buffer
	if err := json.Compact(&buf, b); err != nil {
		t.Fatalf("compact JSON: %v (input: %s)", err, b)
	}
	return buf.Bytes()
}
